import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { MessageCircle, X, ChevronRight, Check, ChevronUp, ChevronDown, Languages, Copy } from "lucide-react";
import { Button } from "@/components/ui/button";
import { isPlausibleApiKey, saveApiKey } from "@/lib/api-key-store";
import { getEncouragement, supportChat } from "@/lib/optimize";
import { toast } from "sonner";
import { useLanguage } from "@/lib/i18n/LanguageContext";
import { LanguageSelector } from "@/components/LanguageSelector";
import type { TranslationKey } from "@/lib/i18n/en";

type Step =
  | "welcome"
  | "tip"
  | "haveKey"
  | "step1"
  | "step2"
  | "step3"
  | "step4"
  | "step5"
  | "step6"
  | "step7"
  | "step8"
  | "pasteNow"
  | "done"
  | "dismissed";

type Message = {
  id: string;
  from: "bot" | "user";
  textKey?: TranslationKey;
  text?: string;
  images?: string[];
  isLanguageSelect?: boolean;
};

type Props = {
  apiKey: string;
  onApiKeyChange: (key: string) => void;
};

const IMG_LOOK_FOR = "data:image/png;base64,";
const IMG_CREATE_KEY = "data:image/png;base64,";
const IMG_DROPDOWN = "data:image/png;base64,";
const IMG_NEW_PROJECT = "data:image/png;base64,";
const IMG_SELECT = "data:image/png;base64,";
const IMG_READY = "data:image/png;base64,";
const IMG_COPY = "data:image/png;base64,";

const STEPS: Record<Step, { textKey: TranslationKey; buttons?: { labelKey: TranslationKey; next: Step }[]; images?: string[] }> = {
  welcome: {
    textKey: "welcome",
    buttons: [
      { labelKey: "letsDoIt", next: "tip" },
      { labelKey: "iHaveMyKey", next: "haveKey" },
    ],
  },

  tip: {
    textKey: "tip",
    buttons: [{ labelKey: "gotIt", next: "step1" }],
  },
  haveKey: {
    textKey: "haveKey",
    buttons: [{ labelKey: "showMeHowToGetIt", next: "tip" }],
  },
  step1: {
    textKey: "step1",
    buttons: [{ labelKey: "imOnThePage", next: "step2" }],
  },
  step2: {
    textKey: "step2",
    images: [IMG_LOOK_FOR],
    buttons: [{ labelKey: "iClickedCreate", next: "step3" }],
  },
  step3: {
    textKey: "step3",
    images: [IMG_CREATE_KEY],
    buttons: [{ labelKey: "iOpenedDropdown", next: "step4" }],
  },
  step4: {
    textKey: "step4",
    images: [IMG_DROPDOWN],
    buttons: [{ labelKey: "next", next: "step5" }],
  },
  step5: {
    textKey: "step5",
    images: [IMG_NEW_PROJECT],
    buttons: [{ labelKey: "projectCreated", next: "step6" }],
  },
  step6: {
    textKey: "step6",
    images: [IMG_SELECT],
    buttons: [{ labelKey: "projectSelected", next: "step7" }],
  },
  step7: {
    textKey: "step7",
    images: [IMG_READY],
    buttons: [{ labelKey: "keyCreated", next: "step8" }],
  },
  step8: {
    textKey: "step8",
    images: [IMG_COPY],
    buttons: [{ labelKey: "iCopiedTheKey", next: "pasteNow" }],
  },

  pasteNow: {
    textKey: "pasteNow",
  },
  done: {
    textKey: "successReady",
  },
  dismissed: {
    textKey: "dismissed",
  },
};

function renderMessageText(text: string, t: (key: TranslationKey) => string) {
  const url = "https://aistudio.google.com/api-keys";
  if (!text.includes(url)) return text;
  const [before, after] = text.split(url);
  return (
    <>
      {before}
      <a
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className="font-medium text-primary underline underline-offset-2 hover:text-primary/80"
      >
        {t("openAiStudio")}
      </a>
      {after}
    </>
  );
}

export function SupportBot({ apiKey, onApiKeyChange }: Props) {
  const { t } = useLanguage();
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState<Step>("welcome");
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const draftRef = useRef<HTMLTextAreaElement>(null);
  const [hasAutoOpened, setHasAutoOpened] = useState(false);
  const [fullscreenImage, setFullscreenImage] = useState<string | null>(null);
  const [encouraging, setEncouraging] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isBotTyping, setIsBotTyping] = useState(false);
  const [inGuidedFlow, setInGuidedFlow] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const hasKey = Boolean(apiKey);
  const { language } = useLanguage();
  const [hasSelectedLanguage, setHasSelectedLanguage] = useState(false);

  useEffect(() => {
    if (!hasKey && !hasAutoOpened) {
      setOpen(true);
      setHasAutoOpened(true);
      pushBot({ textKey: "pleaseSelectLanguage", isLanguageSelect: true });
    }
  }, [hasKey, hasAutoOpened]);

  // After user selects a language from the first message, continue to welcome
  useEffect(() => {
    if (hasSelectedLanguage) return;
    const hasLangMessage = messages.some((m) => m.isLanguageSelect);
    if (hasLangMessage && language) {
      // Small delay so the selection registers
      const timer = setTimeout(() => {
        setHasSelectedLanguage(true);
        goTo("welcome");
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [language, messages, hasSelectedLanguage]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    // Scroll after paint so images and CTAs are included in height
    requestAnimationFrame(() => {
      el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
    });
  }, [messages, open, step, isBotTyping]);

  async function pushBot(opts: { textKey?: TranslationKey; text?: string; images?: string[]; isLanguageSelect?: boolean }) {
    setIsBotTyping(true);
    await new Promise((resolve) => setTimeout(resolve, 1000));
    setMessages((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        from: "bot",
        textKey: opts.textKey,
        text: opts.text,
        images: opts.images,
        isLanguageSelect: opts.isLanguageSelect,
      },
    ]);
    setIsBotTyping(false);
  }

  function pushUser(text: string, images?: string[]) {
    setMessages((prev) => [
      ...prev,
      { id: crypto.randomUUID(), from: "user", text, images: images?.length ? images : undefined },
    ]);
  }

  function goTo(next: Step) {
    setStep(next);
    const nextStep = STEPS[next];
    if (nextStep?.textKey && next !== "dismissed" && next !== "done") {
      pushBot({ textKey: nextStep.textKey, images: nextStep.images });
    }
    if (next === "dismissed") {
      setOpen(false);
    }
  }

  function handleButton(next: Step, labelKey: TranslationKey) {
    pushUser(t(labelKey));
    goTo(next);
  }

  function trySaveKey(raw: string) {
    const trimmed = raw.trim();
    if (!isPlausibleApiKey(trimmed)) return false;
    saveApiKey(trimmed);
    onApiKeyChange(trimmed);
    toast.success(t("geminiKeySaved"));
    pushUser(trimmed.slice(0, 8) + "… " + t("keyDetected"));
    pushBot({ textKey: "successReady" });
    pushBot({ textKey: "liveChatReady" });
    setStep("done");
    setInGuidedFlow(false);
    return true;
  }

  useEffect(() => {
    const el = draftRef.current;
    if (!el) return;
    el.style.height = "0px";
    el.style.height = Math.min(el.scrollHeight, 140) + "px";
  }, [draft, open]);

  async function copyMessage(id: string, value: string) {
    if (!value.trim()) return;
    try {
      await navigator.clipboard.writeText(value);
      setCopiedId(id);
      window.setTimeout(() => {
        setCopiedId((cur) => (cur === id ? null : cur));
      }, 1400);
    } catch {
      toast.error("Could not copy that message.");
    }
  }

  function onDraftKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      onSend();
    }
  }

  async function onSend() {
    const text = draft.trim();
    if (!text) return;
    setDraft("");
    if (trySaveKey(text)) return;

    // Live Gemini chat once a key is saved
    if (hasKey) {
      setIsBotTyping(true);
      const imageUrls = Array.from(text.match(/https?:\/\/[^\s<>"')\]]+/gi) || []).filter((u) =>
        /\.(png|jpe?g|webp|gif|bmp)(\?.*)?$/i.test(u),
      );
      pushUser(text, imageUrls);
      try {
        const history = messages
          .slice(-6)
          .map((m) => ({
            role: m.from === "user" ? ("user" as const) : ("assistant" as const),
            content: (m.text || (m.textKey ? t(m.textKey) : "")).slice(0, 7000),
          }))
          .filter((m) => m.content.trim().length > 0);

        const result = await supportChat({
          data: { apiKey, message: text, history },
        });
        if (result.ok && result.reply?.trim()) {
          const plain = result.reply.trim().replace(/\*\*/g, "").replace(/^\s*[-*]\s+/gm, "");
          await pushBot({ text: plain });
        } else {
          await pushBot({ text: result.error || t("liveChatError") });
        }
      } catch (err) {
        const detail = err instanceof Error ? err.message : "";
        await pushBot({ text: detail || t("liveChatError") });
      }
      return;
    }

    // No key yet — keep the scripted help path
    pushUser(text);
    pushBot({ textKey: "fallbackHelp" });
  }

  if (hasKey && !open) {
    return (
      <button
        type="button"
        onClick={() => {
          setOpen(true);
          if (messages.length === 0) {
            pushBot({ textKey: "liveChatReady" });
          }
        }}
        className="fixed bottom-4 right-4 z-50 flex size-12 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 sm:size-14"
        aria-label={t("openSupport")}
      >
        <MessageCircle className="size-5 sm:size-6" />
      </button>
    );
  }

  return (
    <>
      {!open && (
        <button
          type="button"
          onClick={() => {
            setOpen(true);
            if (messages.length === 0) pushBot({ textKey: "pleaseSelectLanguage", isLanguageSelect: true });
          }}
          className="fixed bottom-4 right-4 z-50 flex size-12 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 sm:size-14"
          aria-label={t("openSupport")}
        >
          <MessageCircle className="size-5 sm:size-6" />
        </button>
      )}

      {open && (
        <div
          className={`fixed right-4 z-50 flex w-[min(100vw-2rem,22rem)] flex-col overflow-hidden rounded-2xl border border-border bg-background shadow-2xl sm:w-96 ${
            isExpanded
              ? "bottom-4 top-4 h-[calc(100dvh-2rem)]"
              : "bottom-4 h-[min(32rem,calc(100dvh-2rem))]"
          }`}
        >
          <header className="flex shrink-0 items-center justify-between gap-2 border-b border-neutral-800 bg-black px-3 py-2">
            <div className="flex items-center gap-2">
              <div
                className="relative size-10 sm:size-12 shrink-0 cursor-pointer"
                role="button"
                aria-label="Click for encouragement"
                onClick={async () => {
                  if (!hasKey || encouraging) return;
                  setEncouraging(true);
                  setIsBotTyping(true);
                  let success = false;
                  const maxAttempts = 5;
                  for (let attempt = 1; attempt <= maxAttempts && !success; attempt++) {
                    try {
                      const result = await getEncouragement({ data: { apiKey } });
                      if (result.ok && result.message?.trim()) {
                        pushBot({ text: result.message.trim() });
                        success = true;
                      }
                    } catch {
                      // treat as failure and retry
                    }
                  }
                  if (!success) {
                    pushBot({ text: "Trust your skills, keep your head up, and take it one step at a time!" });
                  }
                  setEncouraging(false);
                }}
              >
                <video
                  src="/jobs/mascot/supportbot-mascot-original.mp4"
                  autoPlay
                  loop
                  muted
                  playsInline
                  className="absolute inset-0 size-full object-contain pointer-events-none"
                />
              </div>
              <p className="text-sm font-medium text-white">Support</p>
            </div>
            <div className="flex items-center gap-1">
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0 text-white hover:bg-neutral-800 hover:text-white"
                onClick={() => setIsExpanded((v) => !v)}
                aria-label={isExpanded ? "Collapse chat" : "Expand chat to full height"}
              >
                {isExpanded ? <ChevronDown className="size-4" /> : <ChevronUp className="size-4" />}
              </Button>
              <Button type="button" variant="ghost" size="sm" className="h-8 w-8 p-0 text-white hover:bg-neutral-800 hover:text-white" onClick={() => setOpen(false)} aria-label="Minimize">
                <X className="size-4" />
              </Button>
            </div>
          </header>

          <div
            ref={scrollRef}
            className="flex min-h-0 flex-1 flex-col gap-3 overflow-x-hidden overflow-y-auto overscroll-contain px-3 py-3 text-sm"
          >
            {messages.map((m) => (
              <div
                key={m.id}
                className={`grid w-full min-w-0 max-w-[85%] grid-cols-[minmax(0,1fr)_auto] items-stretch gap-1.5 rounded-2xl px-3 py-2 ${
                  m.from === "bot"
                    ? "self-start bg-muted text-foreground"
                    : "self-end bg-primary text-primary-foreground"
                }`}
              >
                <div className="min-w-0 flex-1">
                  {m.isLanguageSelect ? (
                    <div className="flex flex-col gap-2">
                      <div className="whitespace-pre-wrap break-words [overflow-wrap:anywhere]">
                        {t("pleaseSelectLanguage")}
                      </div>
                      <LanguageSelector variant="inline" />
                    </div>
                  ) : (
                    <div className="whitespace-pre-wrap break-words [overflow-wrap:anywhere]">
                      {renderMessageText(m.textKey ? t(m.textKey) : m.text || "", t)}
                    </div>
                  )}
                {m.images && m.images.length > 0 && (
                  <div className="mt-2 flex flex-col gap-2">
                    {m.images.map((src, idx) => (
                      <img
                        key={idx}
                        src={src}
                        alt="Guide screenshot — click to enlarge"
                        className="max-w-full cursor-pointer rounded-md border border-border hover:opacity-90"
                        onClick={() => setFullscreenImage(src)}
                        onLoad={() => {
                          const el = scrollRef.current;
                          if (el) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
                        }}
                      />
                    ))}
                  </div>
                )}
                </div>
                {!m.isLanguageSelect && (
                  <div className="relative w-6 self-stretch">
                    <button
                      type="button"
                      className={`sticky top-1 z-10 flex size-6 items-center justify-center rounded-md ${
                        m.from === "bot"
                          ? "bg-muted text-muted-foreground hover:bg-background/80"
                          : "bg-primary text-primary-foreground/90 hover:bg-primary-foreground/15"
                      }`}
                      aria-label="Copy message"
                      title="Copy"
                      onClick={() =>
                        copyMessage(m.id, m.textKey ? t(m.textKey) : m.text || "")
                      }
                    >
                      {copiedId === m.id ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
                    </button>
                  </div>
                )}
              </div>
            ))}

            {isBotTyping && (
              <div className="max-w-[85%] self-start rounded-2xl bg-muted px-3 py-2">
                <div className="flex items-center gap-1">
                  <span className="size-2 animate-bounce rounded-full bg-foreground/60 [animation-delay:-0.3s]" />
                  <span className="size-2 animate-bounce rounded-full bg-foreground/60 [animation-delay:-0.15s]" />
                  <span className="size-2 animate-bounce rounded-full bg-foreground/60" />
                </div>
              </div>
            )}

            {STEPS[step]?.buttons && step !== "done" && hasSelectedLanguage && (!hasKey || inGuidedFlow) && (
              <div className="flex flex-wrap gap-2">
                {STEPS[step].buttons!.map((b) => (
                  <Button
                    key={b.labelKey}
                    type="button"
                    size="sm"
                    variant="outline"
                    className="h-8"
                    onClick={() => handleButton(b.next, b.labelKey)}
                  >
                    {t(b.labelKey)}
                    <ChevronRight className="size-3.5" />
                  </Button>
                ))}
              </div>
            )}

            {hasKey && !inGuidedFlow && (
              <div className="flex flex-wrap gap-2">
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  className="h-8"
                  onClick={() => {
                    setHasSelectedLanguage(true);
                    setInGuidedFlow(true);
                    goTo("tip");
                  }}
                >
                  {t("getMyKey")}
                  <ChevronRight className="size-3.5" />
                </Button>
              </div>
            )}
          </div>

          <form
            className="flex shrink-0 items-end gap-2 border-t border-border p-2"
            onSubmit={(e) => {
              e.preventDefault();
              onSend();
            }}
          >
            <textarea
              ref={draftRef}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={onDraftKeyDown}
              placeholder={hasKey ? t("askAnythingPlaceholder") : t("pasteKeyPlaceholder")}
              rows={1}
              className="min-h-9 max-h-36 w-full flex-1 resize-none overflow-x-hidden overflow-y-auto whitespace-pre-wrap break-words rounded-lg border border-input bg-background px-3 py-2 text-sm leading-5 shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring [overflow-wrap:anywhere]"
              autoComplete="off"
              spellCheck={false}
            />
            <Button
              type="submit"
              size="sm"
              className="h-9 shrink-0"
              disabled={!draft.trim()}
              title="Send (⌘/Ctrl+Enter)"
              aria-label="Send message"
            >
              <Check className="size-4" />
            </Button>
          </form>
        </div>
      )}

      {fullscreenImage && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 p-4"
          onClick={() => setFullscreenImage(null)}
        >
          <button
            type="button"
            className="absolute right-4 top-4 flex size-10 items-center justify-center rounded-full bg-black/60 text-white hover:bg-black/80"
            onClick={() => setFullscreenImage(null)}
            aria-label="Close full screen image"
          >
            <X className="size-5" />
          </button>
          <img
            src={fullscreenImage}
            alt="Full screen guide"
            className="max-h-full max-w-full rounded-lg object-contain"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </>
  );
}

